<script setup lang="ts">
import { computed, ref } from 'vue'
import { SlidersHorizontal, Link2, Zap, MousePointer2, RotateCcw, Search, Plus, Trash2, X } from 'lucide-vue-next'
import ValueEditor from './ValueEditor.vue'
import StructuredPropertyEditor from './StructuredPropertyEditor.vue'
import JsonValueEditor from './JsonValueEditor.vue'
import BaseButton from './base/BaseButton.vue'
import QuickActionEditor from './QuickActionEditor.vue'
import TranslatableInput from './TranslatableInput.vue'
import ActionEditor from './ActionEditor.vue'
import ContextMenu from './ContextMenu.vue'
import InspectorSection from './InspectorSection.vue'
import LayoutSpecEditor from './LayoutSpecEditor.vue'
import { matchesEditorSearch } from '../lib/editor-search'
import { t } from '../lib/i18n'
import type { MenuItem } from '../lib/context-menu'
import type { Editor } from '../lib/editor'
import type { CustomProperty, LayoutSpec, ValueRef, WidgetPropertySpec } from '../lib/model'
import { commonWidgetPropertyGroups, widgetKinds, newId } from '../lib/model'
const props = defineProps<{ editor: Editor }>()
const tab = ref('properties'), bindingProperty = ref('value'), propertyTargetId = ref(''), propertyTargetName = ref('value'), search = ref(''), newCustomName = ref('')
const contextMenu=ref<{x:number;y:number;items:MenuItem[]}|null>(null)
const widget = computed(() => props.editor.selectedWidgets.value[0])
const selectedWidgets = computed(() => props.editor.selectedWidgets.value)
const parentLayoutType=computed(()=>widget.value?.parentId?props.editor.page.value.widgets.find(item=>item.id===widget.value?.parentId)?.layout?.type:props.editor.page.value.layout?.type)
const layoutManaged=computed(()=>!!parentLayoutType.value&&parentLayoutType.value!=='absolute')
const eventDefinitions=computed(()=>{const kind=widget.value?.kind??'';const result=kind==='button'||kind==='tool-button'?[{name:'click',label:'点击'}]:['list','tree'].includes(kind)?[{name:'selectionChange',label:'选择变化'}]:kind==='table'?[{name:'selectionChange',label:'选择变化'},{name:'cellEdit',label:'单元格编辑'},{name:'rowAction',label:'行操作'},{name:'fileChange',label:'文件变化'}]:['tabs','stack'].includes(kind)?[{name:'tabChange',label:'选项卡切换'}]:kind==='splitter'?[{name:'resize',label:'尺寸变化'}]:kind==='dialog'?[{name:'close',label:'关闭'},{name:'dismiss',label:'点击遮罩'}]:[{name:'change',label:'值变化'}];return result})
const spec = computed(() => widgetKinds.find(item => item.kind === widget.value?.kind))
const expandedSections = ref<Record<string, boolean>>({})
const searching = computed(() => Boolean(search.value.trim()))
function matches(...terms: string[]) { return matchesEditorSearch(search.value, terms, t) }
function isOpen(id: string, initiallyOpen = false) { return searching.value || (expandedSections.value[id] ?? initiallyOpen) }
function toggleSection(id: string, initiallyOpen = false) { expandedSections.value[id] = !(expandedSections.value[id] ?? initiallyOpen) }
const geometryFields = [
  { key: 'x', label: 'X' }, { key: 'y', label: 'Y' },
  { key: 'width', label: '宽度' }, { key: 'height', label: '高度' }, { key: 'zIndex', label: '层级' },
] as const
const constraintFields = computed(() => [
  { key: 'minWidth', label: '最小宽度' }, { key: 'maxWidth', label: '最大宽度' },
  { key: 'minHeight', label: '最小高度' }, { key: 'maxHeight', label: '最大高度' },
  ...(widget.value?.parentId && parentLayoutType.value === 'grid' ? [
    { key: 'row', label: '网格行' }, { key: 'column', label: '网格列' },
    { key: 'rowSpan', label: '行跨度' }, { key: 'columnSpan', label: '列跨度' },
  ] : []),
])
const layoutSearchTerms = computed(() => ['容器布局', '布局方式', 'type', 'layout', '间距', 'gap', '内边距', 'padding',
  ...(widget.value?.layout?.type === 'grid' ? ['列数', 'columns'] : []),
  ...(widget.value?.slots?.length ? ['容器页面与槽位', '槽位标题', 'slots'] : []),
])
const visibleGeometry = computed(() => geometryFields.filter(field => matches('位置与尺寸', field.label, field.key)))
const visibleConstraints = computed(() => constraintFields.value.filter(field => matches('尺寸约束', field.label, field.key)))
const basicVisible = computed(() => matches('基本信息', '控件名称', 'name', '类型', 'kind', '恢复默认属性'))
const constraintsVisible = computed(() => visibleConstraints.value.length > 0 || matches('尺寸约束', '尺寸策略', 'grow', '交叉轴对齐', 'align'))
const layoutVisible = computed(() => Boolean(widget.value?.layout) && matches(...layoutSearchTerms.value))
const customFields = computed(() => Object.entries(widget.value?.customProperties ?? {}).filter(([name]) => matches('自定义业务属性', 'customProperties', name)))
const customVisible = computed(() => customFields.value.length > 0 || matches('自定义业务属性', 'customProperties', '属性名称'))
const fields = computed(() => {
  if (!widget.value) return []
  const content = new Map([...commonWidgetPropertyGroups.basic.filter(field => field.key === 'text'), ...(spec.value?.propertyGroups?.content ?? [])].map(field => [field.key, field]))
  const groups = [
    { id:'content', name:'内容', fields:[...content.values()] },
    ...Object.entries(spec.value?.propertyGroups ?? {}).filter(([name]) => name !== 'content').map(([name, fields])=>({id:name,name:groupTitle(name),fields})),
    { id:'basic', name:'行为', fields:commonWidgetPropertyGroups.basic.filter(field => field.key !== 'text') },
    { id:'appearance', name:'外观', fields:commonWidgetPropertyGroups.appearance },
  ]
  return groups.map(group=>({ ...group, fields:group.fields.filter(field=>matches(group.name,field.label,field.key)) })).filter(group=>group.fields.length)
})
const hasSearchResults = computed(() => basicVisible.value || visibleGeometry.value.length > 0 || constraintsVisible.value || layoutVisible.value || fields.value.length > 0 || customVisible.value)
function geometryValue(key: typeof geometryFields[number]['key'], event: Event) { field(key, ['width', 'height'].includes(key) ? Math.max(1, number(event)) : number(event), false) }
function constraintValue(key: string) { return (widget.value?.layoutItem as Record<string, unknown> | undefined)?.[key] ?? (['row', 'column'].includes(key) ? 0 : ['rowSpan', 'columnSpan'].includes(key) ? 1 : '') }
function updateConstraint(key: string, event: Event) { setLayoutItem(key, ['rowSpan', 'columnSpan'].includes(key) ? Math.max(1, number(event)) : number(event)) }
function groupTitle(name:string) { return ({content:'内容',input:'输入',data:'数据'} as Record<string,string>)[name] ?? name }
function valueOf(field:WidgetPropertySpec) { return widget.value?.props[field.key] ?? field.default ?? commonDefault(field.key) }
function commonDefault(key:string) { for (const group of Object.values(commonWidgetPropertyGroups)) { const field=group.find(item=>item.key===key); if(field) return field.default }; return undefined }
function field(key:string, value:any, property=true) { if (!selectedWidgets.value.length) return; props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{ if(property) item.props[key]=value; else (item as any)[key]=value })) }
function setLayout(key:string,value:any) { if (!widget.value) return; if(key==='type'){for(const item of selectedWidgets.value)props.editor.setContainerLayout(item.id,value);return} props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{ item.layout ??= {type:'absolute',gap:8,padding:8}; (item.layout as any)[key]=value })) }
function setPageLayout(value:any){props.editor.setContainerLayout(undefined,value)}
function applyWidgetLayout(value: LayoutSpec) { for(const item of selectedWidgets.value)if(item.layout?.type!==value.type)props.editor.setContainerLayout(item.id,value.type);props.editor.mutate(()=>selectedWidgets.value.forEach(item=>item.layout={...value})) }
function applyPageLayout(value: LayoutSpec) { if(props.editor.page.value.layout?.type!==value.type)props.editor.setContainerLayout(undefined,value.type);props.editor.mutate(()=>props.editor.page.value.layout={...value}) }
function addSlot(){props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{item.slots??=[];const id=newId('slot');item.slots.push({id,title:{i18nKey:`${item.id}.${id}.title`,fallback:`页面 ${item.slots.length+1}`}});item.props.activeSlot=id;props.editor.activeSlots.value[item.id]=id}))}
function removeSlot(slotId:string){if(selectedWidgets.value.some(item=>(item.slots?.length??0)<2))return;props.editor.mutate(project=>{for(const item of selectedWidgets.value){const page=project.pages.find(candidate=>candidate.widgets.some(widget=>widget.id===item.id));if(!page)continue;const pageWidgets=page.widgets,removed=new Set<string>();function collect(parentId:string,slot?:string){for(const child of pageWidgets.filter(widget=>widget.parentId===parentId&&(slot===undefined||(widget.slotId??'content')===slot))){if(removed.has(child.id))continue;removed.add(child.id);collect(child.id)}}collect(item.id,slotId);page.widgets=pageWidgets.filter(widget=>!removed.has(widget.id));item.slots=item.slots?.filter(slot=>slot.id!==slotId);if(item.props.activeSlot===slotId)item.props.activeSlot=item.slots?.[0]?.id??''}props.editor.selected.value=props.editor.selected.value.filter(id=>project.pages.some(page=>page.widgets.some(widget=>widget.id===id)))})}
function updateSlotTitle(slotId:string,value:any){props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{const slot=item.slots?.find(candidate=>candidate.id===slotId);if(slot)slot.title=value}))}
function setLayoutItem(key:string,value:any) { if (!widget.value) return; props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{ item.layoutItem ??= {}; (item.layoutItem as any)[key]=value })) }
function setSizeMode(axis:'width'|'height',mode:string){if(!['fixed','fit','fill'].includes(mode))return;props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{item.layoutItem??={};item.layoutItem.size??={};const current=item.layoutItem.size[axis];item.layoutItem.size[axis]={mode:mode as 'fixed'|'fit'|'fill',...(current?.value!==undefined?{value:current.value}:{})}}))}
function number(event:Event) { return Number((event.target as HTMLInputElement).value) }
function binding(key:string,value:ValueRef) { props.editor.mutate(()=>selectedWidgets.value.forEach(item=>item.bindings[key]=value)) }
function bindEvent(name:string,event:Event) { const [flowId,entryNodeId]=(event.target as HTMLSelectElement).value.split(':'); props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{ if(!flowId) delete item.events[name]; else item.events[name]={kind:'flow',flowId,entryNodeId} })) }
function setSharedAction(event:Event) { const id=(event.target as HTMLSelectElement).value; const name=['button','tool-button'].includes(widget.value?.kind ?? '')?'click':'change'; props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{ if(!id) delete item.events[name]; else item.events[name]={kind:'shared',flowId:'',actionId:id} })) }
function resetProperty(field:WidgetPropertySpec) { const val = field.default ?? commonDefault(field.key); fieldValue(field.key, val) }
function fieldValue(key:string,value:any) { field(key,value,true) }
function openPropertyMenu(event:MouseEvent,property:WidgetPropertySpec){const key=property.key;contextMenu.value={x:event.clientX,y:event.clientY,items:[{label:'恢复默认值',action:()=>resetProperty(property)},{label:'设置绑定',items:props.editor.project.value.variables.map(variable=>({label:variable.name,action:()=>binding(key,{source:'variable',key:variable.id})})),disabled:!props.editor.project.value.variables.length},{label:'清除绑定',disabled:!widget.value?.bindings[key],action:()=>props.editor.mutate(()=>selectedWidgets.value.forEach(item=>delete item.bindings[key]))}]}}
function resetAll() { const shared=Object.fromEntries(Object.values(commonWidgetPropertyGroups).flat().map(item=>[item.key,item.default])); props.editor.mutate(()=>selectedWidgets.value.forEach(item=>item.props={...shared,...(widgetKinds.find(candidate=>candidate.kind===item.kind)?.defaults ?? {})})) }
function addCustomProperty() { const name=newCustomName.value.trim(); if(!name||!selectedWidgets.value.length) return; props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{ item.customProperties ??={}; item.customProperties[name] ??={type:'string',value:''} })); newCustomName.value='' }
function updateCustom(name:string,key:keyof CustomProperty,value:any) { props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{ if(item.customProperties?.[name]) (item.customProperties[name] as any)[key]=value })) }
function updateCustomType(name:string,type:CustomProperty['type']){const initial:any={string:'',number:0,boolean:false,enum:'',object:{},array:[]};props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{const property=item.customProperties?.[name];if(!property)return;property.type=type;property.value=initial[type];if(type==='enum'){property.options??=[];property.value=property.options[0]??''}}))}
function updateCustomJson(name:string,key:'value'|'options',event:Event){try{updateCustom(name,key,JSON.parse((event.target as HTMLTextAreaElement).value))}catch{/* Keep the last valid typed value until valid JSON is entered. */}}
function removeCustom(name:string) { props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{ if(item.customProperties) delete item.customProperties[name] })) }
function addMenuGroup(){props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{item.props.groups??=[];item.props.groups.push({id:newId('menu'),title:'菜单项',actionIds:[]})}))}
function updateMenuGroup(id:string,key:string,value:any){props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{const group=item.props.groups?.find((candidate:any)=>candidate.id===id);if(group)group[key]=value}))}
function toggleMenuGroupAction(id:string,actionId:string,checked:boolean){props.editor.mutate(()=>selectedWidgets.value.forEach(item=>{const group=item.props.groups?.find((candidate:any)=>candidate.id===id);if(!group)return;group.actionIds??=[];if(checked&&!group.actionIds.includes(actionId))group.actionIds.push(actionId);if(!checked)group.actionIds=group.actionIds.filter((item:string)=>item!==actionId)}))}
function removeMenuGroup(id:string){props.editor.mutate(()=>selectedWidgets.value.forEach(item=>item.props.groups=item.props.groups?.filter((candidate:any)=>candidate.id!==id)??[]))}
function text(value:any) { return typeof value==='object' && value ? value.fallback ?? value.i18nKey ?? '' : String(value ?? '') }
function structuredKind(key:string):'columns'|'segments'|'byteRange'|undefined { if(widget.value?.kind==='table'&&key==='columns')return 'columns';if(widget.value?.kind==='memory-map'&&key==='segments')return 'segments';if(widget.value?.kind==='byte-range'&&key==='value')return 'byteRange';return undefined }
function fieldControlType(field:WidgetPropertySpec) { return field.type==='color'?'color':field.type==='number'?'number':field.type==='boolean'?'checkbox':field.type==='enum'?'select':field.type==='asset'?'asset':field.type==='json'?'json':'text' }
function fieldOptions(key:string) { const fields=[...Object.values(commonWidgetPropertyGroups).flat(),...Object.values(spec.value?.propertyGroups??{}).flat()];return fields.find(item=>item.key===key)?.options ?? [] }
</script>
<template>
  <aside class="inspector">
    <div class="panel-title">{{ widget ? '控件设置' : '页面设置' }}<span v-if="selectedWidgets.length>1" class="tiny-badge">{{ selectedWidgets.length }} 个选中</span></div>
    <template v-if="widget">
      <div class="inspector-object"><span class="object-symbol"><MousePointer2 :size="18" /></span><div><strong data-project-text>{{ widget.name }}</strong><small>{{ widget.kind }} · {{ widget.id.slice(-8) }}</small></div></div>
      <div class="inspector-tabs"><button :class="{active:tab==='properties'}" @click="tab='properties'"><SlidersHorizontal :size="14"/>属性</button><button :class="{active:tab==='bindings'}" @click="tab='bindings'"><Link2 :size="14"/>绑定</button><button :class="{active:tab==='events'}" @click="tab='events'"><Zap :size="14"/>事件</button></div>
      <div v-if="tab==='properties'" class="inspector-scroll" :inert="editor.readOnly.value">
        <div class="inspector-search"><Search :size="14"/><input v-model="search" :placeholder="t('搜索属性…')" :aria-label="t('搜索属性')"/><button v-if="search" class="icon-button" :title="t('清除搜索')" @click="search=''"><X :size="13"/></button></div>
        <InspectorSection v-show="basicVisible" title="基本信息" data-section="general" :open="isOpen('general',true)" :forced-open="searching" @toggle="toggleSection('general',true)">
          <label v-show="matches('基本信息','控件名称','name')">控件名称<input :value="widget.name" @change="field('name',($event.target as HTMLInputElement).value,false)"/></label>
          <label v-show="matches('基本信息','类型','kind')">类型<input :value="widget.kind" disabled/></label>
          <button v-show="matches('基本信息','恢复默认属性')" class="text-button" @click="resetAll"><RotateCcw :size="13"/>恢复默认属性</button>
        </InspectorSection>
        <InspectorSection v-show="visibleGeometry.length" title="位置与尺寸" data-section="geometry" :open="isOpen('geometry',true)" :forced-open="searching" @toggle="toggleSection('geometry',true)">
          <div class="property-grid"><label v-for="property in visibleGeometry" :key="property.key">{{ t(property.label) }}<small v-if="layoutManaged && ['x','y'].includes(property.key)" class="layout-managed-hint">由布局控制</small><input type="number" :min="['width','height'].includes(property.key)?1:undefined" :value="widget[property.key]" :disabled="layoutManaged && ['x','y'].includes(property.key)" @change="geometryValue(property.key,$event)"/></label></div>
        </InspectorSection>
        <InspectorSection v-show="layoutVisible" title="容器布局" data-section="layout" :open="isOpen('layout',true)" :forced-open="searching" @toggle="toggleSection('layout',true)">
          <template v-if="widget.layout">
            <LayoutSpecEditor :model-value="widget.layout" label-prefix="Container layout" @update:model-value="applyWidgetLayout" />
            <div v-if="widget.slots?.length" class="slot-editor"><h4>容器页面与槽位</h4><div v-for="slot in widget.slots" :key="slot.id" class="slot-editor-row"><TranslatableInput :model-value="slot.title" label="槽位标题" @update:model-value="updateSlotTitle(slot.id,$event)"/><button class="text-button" :disabled="widget.slots.length<2" title="删除槽位及其子控件" @click="removeSlot(slot.id)"><Trash2 :size="12"/>删除</button></div><button class="text-button" @click="addSlot"><Plus :size="13"/>添加页面</button></div>
          </template>
        </InspectorSection>
        <InspectorSection v-for="group in fields" :key="group.id" :title="group.name" :data-section="group.id" :open="isOpen(group.id,!['appearance','basic'].includes(group.id))" :forced-open="searching" @toggle="toggleSection(group.id,!['appearance','basic'].includes(group.id))"><label v-for="property in group.fields" :key="property.key" @contextmenu.self.prevent="openPropertyMenu($event,property)">{{ property.label }}<TranslatableInput v-if="property.translatable" :model-value="valueOf(property)" :label="property.label" @update:model-value="field(property.key,$event)"/><StructuredPropertyEditor v-else-if="structuredKind(property.key)" :kind="structuredKind(property.key)!" :model-value="valueOf(property)" @update:model-value="field(property.key,$event)"/><JsonValueEditor v-else-if="fieldControlType(property)==='json'" :model-value="valueOf(property)" :label="property.label" @update:model-value="field(property.key,$event)"/><input v-else-if="fieldControlType(property)==='text'" :value="text(valueOf(property))" @change="field(property.key,($event.target as HTMLInputElement).value)"/><input v-else-if="fieldControlType(property)==='color'" type="color" :value="valueOf(property) || '#ffffff'" @change="field(property.key,($event.target as HTMLInputElement).value)"/><input v-else-if="fieldControlType(property)==='number'" type="number" :value="valueOf(property)" @change="field(property.key,number($event))"/><input v-else-if="fieldControlType(property)==='checkbox'" type="checkbox" :checked="Boolean(valueOf(property))" @change="field(property.key,($event.target as HTMLInputElement).checked)"/><select v-else-if="fieldControlType(property)==='select'" :value="valueOf(property)" @change="field(property.key,($event.target as HTMLSelectElement).value)"><option v-for="option in fieldOptions(property.key)" :key="option" :value="option">{{ option }}</option></select><select v-else-if="fieldControlType(property)==='asset'" :value="widget.props[property.key] ?? ''" @change="field(property.key,($event.target as HTMLSelectElement).value)"><option value="">请选择资源</option><option v-for="asset in editor.project.value.assets" :key="asset.id" :value="asset.id">{{ asset.path.split('/').pop() }}</option></select><button class="property-reset" :title="`恢复${property.label}默认值`" @click="resetProperty(property)"><RotateCcw :size="12"/></button></label></InspectorSection>
        <InspectorSection v-show="constraintsVisible" title="尺寸约束" data-section="constraints" :open="isOpen('constraints')" :forced-open="searching" @toggle="toggleSection('constraints')">
          <div class="property-grid"><label v-for="property in visibleConstraints" :key="property.key">{{ t(property.label) }}<input type="number" :min="['row','column'].includes(property.key)?0:['rowSpan','columnSpan'].includes(property.key)?1:undefined" :value="constraintValue(property.key)" @change="updateConstraint(property.key,$event)"/></label></div>
          <div class="property-grid"><label>Width mode<select aria-label="Width size mode" :value="widget.layoutItem?.size?.width?.mode ?? 'fixed'" @change="setSizeMode('width',($event.target as HTMLSelectElement).value)"><option value="fixed">Fixed</option><option value="fit">Fit</option><option value="fill">Fill</option></select></label><label>Height mode<select aria-label="Height size mode" :value="widget.layoutItem?.size?.height?.mode ?? 'fixed'" @change="setSizeMode('height',($event.target as HTMLSelectElement).value)"><option value="fixed">Fixed</option><option value="fit">Fit</option><option value="fill">Fill</option></select></label></div>
          <label v-show="matches('尺寸约束','尺寸策略','grow')">尺寸策略<select :value="widget.layoutItem?.grow ? 'grow':'fixed'" @change="setLayoutItem('grow',($event.target as HTMLSelectElement).value==='grow'?1:0)"><option value="fixed">固定</option><option value="grow">可伸缩</option></select></label>
          <label v-show="matches('尺寸约束','交叉轴对齐','align')">交叉轴对齐<select :value="widget.layoutItem?.align ?? 'stretch'" @change="setLayoutItem('align',($event.target as HTMLSelectElement).value)"><option value="start">起始</option><option value="center">居中</option><option value="end">结束</option><option value="stretch">拉伸</option></select></label>
        </InspectorSection>
        <InspectorSection v-show="customVisible" title="自定义业务属性" data-section="custom" :open="isOpen('custom')" :forced-open="searching" @toggle="toggleSection('custom')"><div v-for="[name,custom] in customFields" :key="name" class="custom-property"><strong data-project-text>{{ name }}</strong><select :value="custom.type" @change="updateCustomType(name,($event.target as HTMLSelectElement).value as any)"><option value="string">文本</option><option value="number">数值</option><option value="boolean">布尔</option><option value="enum">枚举</option><option value="object">对象</option><option value="array">数组</option></select><JsonValueEditor v-if="custom.type==='object'||custom.type==='array'" :model-value="custom.value" :type="custom.type" @update:model-value="updateCustom(name,'value',$event)"/><textarea v-else-if="custom.type==='enum'" :value="JSON.stringify(custom.options ?? [],null,2)" rows="2" aria-label="枚举选项 JSON" @change="updateCustomJson(name,'options',$event)"/><select v-if="custom.type==='enum'" :value="String(custom.value ?? '')" @change="updateCustom(name,'value',($event.target as HTMLSelectElement).value)"><option v-for="option in custom.options ?? []" :key="option" :value="option">{{option}}</option></select><input v-else-if="custom.type==='boolean'" type="checkbox" :checked="Boolean(custom.value)" @change="updateCustom(name,'value',($event.target as HTMLInputElement).checked)"/><input v-else-if="custom.type!=='array'&&custom.type!=='object'" :type="custom.type==='number'?'number':'text'" :value="custom.value as any" @change="updateCustom(name,'value',custom.type==='number'?number($event):($event.target as HTMLInputElement).value)"/><ValueEditor :model-value="custom.binding ?? {source:'literal',value:custom.value}" :project="editor.project.value" @update:model-value="updateCustom(name,'binding',$event)"/><label>变更时触发<select :value="custom.event ? `${custom.event.flowId}:${custom.event.entryNodeId ?? ''}` : ''" @change="(()=>{const [flowId,entryNodeId]=($event.target as HTMLSelectElement).value.split(':');updateCustom(name,'event',flowId?{kind:'flow',flowId,entryNodeId}:undefined)})()"><option value="">无事件</option><template v-for="flow in editor.project.value.flows" :key="flow.id"><option v-for="node in flow.nodes.filter(n=>n.kind==='trigger.ui')" :key="node.id" :value="`${flow.id}:${node.id}`" data-project-text>{{ flow.name }} / {{ node.label }}</option></template></select></label><button class="text-button" @click="removeCustom(name)"><Trash2 :size="12"/>删除</button></div><div v-if="!searching || matches('自定义业务属性','customProperties','属性名称')" class="custom-add"><input v-model="newCustomName" placeholder="属性名称" @keydown.enter.prevent="addCustomProperty"/><BaseButton @click="addCustomProperty"><Plus :size="13"/>添加</BaseButton></div></InspectorSection>
        <p v-if="!hasSearchResults" class="inspector-no-results" role="status">{{ t('没有匹配的属性') }}</p>
      </div>
      <div v-else-if="tab==='bindings'" class="inspector-scroll" :inert="editor.readOnly.value"><section class="property-section"><p class="muted-copy">将控件属性连接到项目变量、设备数据或其他控件属性。</p><div v-for="(value,key) in widget.bindings" :key="key" class="binding-card"><div class="inline-between"><strong>{{ key }}</strong><button class="text-button" @click="editor.mutate(()=>selectedWidgets.forEach(item=>delete item.bindings[key]))">移除</button></div><ValueEditor :model-value="value" :project="editor.project.value" @update:model-value="binding(key,$event)"/></div><label>绑定属性<select v-model="bindingProperty"><option v-for="property in Object.keys(widget.props)" :key="property" :value="property">{{ property }}</option><option v-for="(property,key) in widget.customProperties" :key="key" :value="key">{{ key }}</option></select></label><BaseButton class="full-width" @click="binding(bindingProperty,{source:'variable',key:editor.project.value.variables[0]?.id ?? ''})"><Link2 :size="14"/>添加变量绑定</BaseButton><label>来源控件<select v-model="propertyTargetId"><option value="">选择控件</option><option v-for="item in editor.page.value.widgets.filter(item=>item.id!==widget.id)" :key="item.id" :value="item.id" data-project-text>{{ item.name }}</option></select></label><label>来源属性<select v-model="propertyTargetName"><option v-for="property in Object.keys(editor.page.value.widgets.find(item=>item.id===propertyTargetId)?.props ?? {})" :key="property" :value="property">{{ property }}</option></select></label><BaseButton class="full-width" :disabled="!propertyTargetId" @click="binding(bindingProperty,{source:'property',key:propertyTargetId,property:propertyTargetName})">添加控件属性绑定</BaseButton></section></div>
      <div v-else class="inspector-scroll" :inert="editor.readOnly.value"><QuickActionEditor :editor="editor" :widget="widget"/><section v-if="['menu','toolbar'].includes(widget.kind)" class="property-section"><h4>显示共享动作</h4><label v-for="action in editor.project.value.actions ?? []" :key="action.id" class="checkbox-label"><input type="checkbox" :checked="(widget.props.items ?? []).includes(action.id)" @change="editor.mutate(()=>selectedWidgets.forEach(item=>{item.props.items ??=[]; const ids=item.props.items as string[]; const checked=($event.target as HTMLInputElement).checked; if(checked&&!ids.includes(action.id))ids.push(action.id); if(!checked)item.props.items=ids.filter(id=>id!==action.id)}))"><span data-project-text>{{ text(action.text) }}</span></label><p v-if="!editor.project.value.actions?.length" class="muted-copy">先添加共享动作，再分配到菜单或工具栏。</p></section><section v-if="widget.kind==='menu'" class="property-section"><h4>下拉菜单分组</h4><article v-for="group in widget.props.groups ?? []" :key="group.id" class="menu-group-config"><div class="inline-between"><input :value="group.title" aria-label="菜单标题" @change="updateMenuGroup(group.id,'title',($event.target as HTMLInputElement).value)"><button class="text-button" @click="removeMenuGroup(group.id)">删除分组</button></div><label v-for="action in editor.project.value.actions ?? []" :key="action.id" class="checkbox-label"><input type="checkbox" :checked="(group.actionIds ?? []).includes(action.id)" @change="toggleMenuGroupAction(group.id,action.id,($event.target as HTMLInputElement).checked)"><span data-project-text>{{text(action.text)}}</span></label></article><button class="text-button" @click="addMenuGroup">＋ 添加下拉分组</button></section><InspectorSection title="触发共享动作" :open="expandedSections['shared-trigger'] ?? false" @toggle="toggleSection('shared-trigger')"><label>共享动作<select :value="Object.values(widget.events).find(action=>action.kind==='shared')?.actionId ?? ''" @change="setSharedAction"><option value="">无共享动作</option><option v-for="action in editor.project.value.actions ?? []" :key="action.id" :value="action.id" data-project-text>{{ text(action.text) }}</option></select></label></InspectorSection><section class="property-section"><div v-for="definition in eventDefinitions" :key="definition.name" class="widget-event-binding"><h4>{{definition.label}}</h4><label>业务流程<select :value="widget.events[definition.name]?.kind==='flow'?`${widget.events[definition.name]?.flowId}:${widget.events[definition.name]?.entryNodeId}`:''" @change="bindEvent(definition.name,$event)"><option value="">无操作</option><template v-for="flow in editor.project.value.flows" :key="flow.id"><option v-for="node in flow.nodes.filter(n=>n.kind==='trigger.ui')" :key="node.id" :value="`${flow.id}:${node.id}`" data-project-text>{{ flow.name }} / {{ node.label }}</option></template></select></label></div><p class="muted-copy">事件名称和负载可在逻辑流程中读取。</p><h4>运行管理</h4><label class="checkbox-label"><input type="checkbox" :checked="Object.values(widget.events).some(action=>action.kind==='runtimeRetry')" @change="editor.mutate(()=>selectedWidgets.forEach(item=>{const eventName=['button','tool-button'].includes(item.kind)?'click':'change';if(($event.target as HTMLInputElement).checked)item.events[eventName]={kind:'runtimeRetry',flowId:''};else if(item.events[eventName]?.kind==='runtimeRetry')delete item.events[eventName]}))"/>Retry runtime when failed</label><label>宿主控制<select :value="Object.values(widget.events).find(action=>action.kind==='startFlow'||action.kind==='stopFlow') ? `${Object.values(widget.events).find(action=>action.kind==='startFlow'||action.kind==='stopFlow')?.kind}:${Object.values(widget.events).find(action=>action.kind==='startFlow'||action.kind==='stopFlow')?.flowId}` : ''" @change="editor.mutate(()=>{const [kind,flowId]=($event.target as HTMLSelectElement).value.split(':'); selectedWidgets.forEach(item=>{const name=['button','tool-button'].includes(item.kind)?'click':'change'; if(flowId)item.events[name]={kind:kind as 'startFlow'|'stopFlow',flowId};else delete item.events[name]})})"><option value="">无管理操作</option><template v-for="flow in editor.project.value.flows" :key="flow.id"><option :value="`startFlow:${flow.id}`" data-project-text>恢复：{{ flow.name }}</option><option :value="`stopFlow:${flow.id}`" data-project-text>停止：{{ flow.name }}</option></template></select></label></section><InspectorSection title="共享动作管理" data-section="shared-actions" :open="expandedSections['shared-actions'] ?? false" @toggle="toggleSection('shared-actions')"><ActionEditor :actions="editor.project.value.actions ?? []" :flows="editor.project.value.flows" :disabled="editor.readOnly.value" @update:actions="editor.mutate(project=>project.actions=$event)"/></InspectorSection></div>
    </template>
    <div v-else class="inspector-scroll" :inert="editor.readOnly.value"><section class="property-section"><label>页面名称<input :value="editor.page.value.name" @change="editor.mutate(()=>editor.page.value.name=($event.target as HTMLInputElement).value)"/></label><h4>项目画布</h4><label>Runtime chrome<select :value="editor.project.value.presentation?.chrome ?? 'host'" @change="editor.mutate(project=>project.presentation={chrome:($event.target as HTMLSelectElement).value as 'project'|'host'})"><option value="host">Host toolbar</option><option value="project">Project components only</option></select></label><div class="property-grid"><label>宽度<input type="number" min="100" :value="editor.project.value.width" @change="editor.mutate(p=>p.width=Math.max(100,number($event)))"/></label><label>高度<input type="number" min="100" :value="editor.project.value.height" @change="editor.mutate(p=>p.height=Math.max(100,number($event)))"/></label></div><label class="checkbox-label"><input type="checkbox" :checked="editor.page.value.responsive !== false" :disabled="(editor.page.value.layout?.type ?? 'absolute') === 'absolute'" @change="editor.mutate(()=>editor.page.value.responsive=($event.target as HTMLInputElement).checked)"/>自适应布局</label><p v-if="(editor.page.value.layout?.type ?? 'absolute') === 'absolute'" class="muted-copy">绝对定位页面按设计尺寸等比缩放；切换为水平、垂直、网格或表单布局后可启用自适应。</p><LayoutSpecEditor :model-value="editor.page.value.layout ?? {type:'absolute',gap:8,padding:8}" label-prefix="Page layout" @update:model-value="applyPageLayout" /><p class="muted-copy">页面画布、布局和控件在设计器与运行预览中共用。</p></section><InspectorSection title="快捷操作" :open="expandedSections['shortcuts'] ?? false" @toggle="toggleSection('shortcuts')"><div class="shortcut"><span>撤销 / 重做</span><kbd>Ctrl Z / Y</kbd></div><div class="shortcut"><span>复制控件</span><kbd>Ctrl D</kbd></div><div class="shortcut"><span>删除控件</span><kbd>Delete</kbd></div></InspectorSection></div>
    <ContextMenu v-if="contextMenu" :items="contextMenu.items" :x="contextMenu.x" :y="contextMenu.y" @close="contextMenu=null"/>
  </aside>
</template>
